package com.netbanking.account.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="ACCOUNT_TYPE_HISTORY") public class AccountTypeHistory { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="HISTORY_ID") private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="ACCOUNT_ID") private Account account; @Enumerated(EnumType.STRING) @Column(name="OLD_ACCOUNT_TYPE") private AccountType oldType; @Enumerated(EnumType.STRING) @Column(name="NEW_ACCOUNT_TYPE") private AccountType newType; @Column(name="CHANGED_BY") private String changedBy; private String reason; @Column(name="CHANGED_AT") private LocalDateTime changedAt; protected AccountTypeHistory(){} public AccountTypeHistory(Account a,AccountType o,AccountType n,String by,String reason){account=a;oldType=o;newType=n;changedBy=by;this.reason=reason;} @PrePersist void created(){changedAt=LocalDateTime.now();} }
